  // so an authored child config replaces rather than field-merges the base axis.
  const color = own.color ?? inherited?.color;
  const radius = own.radius ? {
    ...inherited?.radius,
    ...own.radius
  } : inherited?.radius;
  const motion = own.motion ? {
    ...inherited?.motion,
    ...own.motion
  } : inherited?.motion;
